export type OperationId = keyof OperationTypes & keyof typeof OPERATIONS;
export type OperationPath<Id extends OperationId> = OperationTypes[Id]['path'];
export type OperationQuery<Id extends OperationId> = OperationTypes[Id]['query'];
export type OperationInput<Id extends OperationId> = OperationTypes[Id]['input'];
export type OperationResponse<Id extends OperationId> = OperationTypes[Id]['response'];
